{
    Ok(!TryParsePort("abc", out var port));
    Eq(port, 0, "a failed Try must not leave a stale value behind");
});

Test("null is rejected", () => Ok(!TryParsePort(null, out _)));

Test("Swap swaps the caller's variables", () =>
{
    var a = 1;
    var b = 2;
    Swap(ref a, ref b);
    Eq((a, b), (2, 1));
});

